END $reserve$;
COMMIT;
BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $payload$
DECLARE payload jsonb; data jsonb; started timestamptz:=clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-ca4dae79993eb719e09e8f18de04' AND status='running' AND operation_hash='ca4dae79993eb719e09e8f18de0469d3b050356fa825ca3ec55c3c81a2e5fa09' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO data FROM (SELECT clock_timestamp() AS checked_at,
      (SELECT count(*)::int FROM pg_stat_activity) AS connections,
      (SELECT count(*)::int FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid))>0) AS blocked,
      (SELECT count(*)::int FROM pg_stat_activity WHERE pid<>pg_backend_pid() AND state='active' AND query_start<clock_timestamp()-interval '30 seconds') AS active_older_30s,
      (SELECT to_jsonb(b) FROM comparator_strict.execution_budget b WHERE budget_date=DATE '2026-09-03' AND project_ref='gkffvigcnsesbaihycay') AS budget,
      (SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid))) FROM pg_constraint WHERE conrelid='comparator_strict.execution_budget'::regclass) AS constraints,
      (SELECT bool_and(relrowsecurity) FROM pg_class WHERE relnamespace='comparator_strict'::regnamespace AND relkind='r') AS private_rls,
      has_schema_privilege('anon','comparator_strict','USAGE') AS anon_usage,
      has_schema_privilege('authenticated','comparator_strict','USAGE') AS authenticated_usage,
      has_schema_privilege('service_role','comparator_strict','USAGE') AS service_usage) q;
  payload:=jsonb_build_object('job_key','ce1-ce200-ca4dae79993eb719e09e8f18de04','operation_hash','ca4dae79993eb719e09e8f18de0469d3b050356fa825ca3ec55c3c81a2e5fa09',
    'project_ref','gkffvigcnsesbaihycay','captured_at',started,'kind','health','store',null,
    'cursor','','rows',data,'row_count',jsonb_array_length(data),'elapsed_ms',extract(epoch FROM clock_timestamp()-started)*1000);
  IF jsonb_array_length(data)>1 OR octet_length(payload::text)>122880 THEN RAISE EXCEPTION 'ce200_result_limit'; END IF;
  UPDATE comparator_strict.execution_jobs SET status='succeeded',finished_at=clock_timestamp(),
    receipt=jsonb_build_object('payload_sha256',encode(sha256(convert_to(payload::text,'UTF8')),'hex'),'row_count',jsonb_array_length(data),'payload_bytes',octet_length(payload::text),'elapsed_ms',payload->'elapsed_ms') WHERE job_key='ce1-ce200-ca4dae79993eb719e09e8f18de04';
  PERFORM set_config('comparator_strict.ce200_response',payload::text,true);
END $payload$;
SELECT current_setting('comparator_strict.ce200_response')::jsonb AS evidence;
